class UserAccount {
  String username, name, role, passwordHash;
  UserAccount({required this.username, required this.name, required this.role, required this.passwordHash});
  Map<String,dynamic> toJson()=>{'username':username,'name':name,'role':role,'passwordHash':passwordHash};
  factory UserAccount.fromJson(Map<String,dynamic> j)=>UserAccount(username:'${j['username']}',name:'${j['name']}',role:'${j['role']}',passwordHash:'${j['passwordHash']}');
}

class Property {
  String code,type,title,address,owner,phone,price,area,rooms,year,link,desc,agent;
  Property({required this.code,required this.type,required this.title,required this.address,required this.owner,required this.phone,required this.price,required this.area,required this.rooms,required this.year,required this.link,required this.desc,required this.agent});
  Map<String,dynamic> toJson()=>{'code':code,'type':type,'title':title,'address':address,'owner':owner,'phone':phone,'price':price,'area':area,'rooms':rooms,'year':year,'link':link,'desc':desc,'agent':agent};
  factory Property.fromJson(Map<String,dynamic> j)=>Property(code:'${j['code']??''}',type:'${j['type']??'آپارتمان'}',title:'${j['title']??''}',address:'${j['address']??''}',owner:'${j['owner']??''}',phone:'${j['phone']??''}',price:'${j['price']??''}',area:'${j['area']??''}',rooms:'${j['rooms']??''}',year:'${j['year']??''}',link:'${j['link']??''}',desc:'${j['desc']??''}',agent:'${j['agent']??''}');
}

final properties=<Property>[];
final clients=<String>[];
final meetings=<String>[];
UserAccount? currentUser;

String hashPassword(String value)=>sha256.convert(utf8.encode(value)).toString();

class Store {
  static const pKey='mirath_properties_v3', cKey='mirath_clients_v2', mKey='mirath_meetings_v2', uKey='mirath_users_v1', themeKey='mirath_dark_theme';
  static Future<SharedPreferences> prefs()=>SharedPreferences.getInstance();
  static Future<void> load() async {
    final p=await prefs();
    try { properties..clear()..addAll((jsonDecode(p.getString(pKey)??'[]') as List).map((e)=>Property.fromJson(Map<String,dynamic>.from(e)))); } catch(_){ }
    clients..clear()..addAll(p.getStringList(cKey)??[]); meetings..clear()..addAll(p.getStringList(mKey)??[]);
  }
  static Future<List<UserAccount>> users() async { final p=await prefs(); final raw=p.getString(uKey); if(raw==null){ final list=[UserAccount(username:'admin',name:'مهندس مجتبی صفری',role:'مدیر',passwordHash:hashPassword('1234')),UserAccount(username:'tahmasbipour',name:'خانم طهماسبی پور',role:'مدیر فروش',passwordHash:hashPassword('1234'))]; await p.setString(uKey,jsonEncode(list.map((x)=>x.toJson()).toList())); return list;} return (jsonDecode(raw) as List).map((e)=>UserAccount.fromJson(Map<String,dynamic>.from(e))).toList(); }
  static Future<void> saveUsers(List<UserAccount> list) async => (await prefs()).setString(uKey,jsonEncode(list.map((x)=>x.toJson()).toList()));
  static Future<void> saveAll() async { final p=await prefs(); await p.setString(pKey,jsonEncode(properties.map((e)=>e.toJson()).toList())); await p.setStringList(cKey,clients); await p.setStringList(mKey,meetings); }
  static Future<bool> dark() async=>(await prefs()).getBool(themeKey)??false;
  static Future<void> setDark(bool v) async=>(await prefs()).setBool(themeKey,v);
}

