class DivarImporter { static Future<Property> fetch(String url) async { final r=await http.get(Uri.parse(url),headers:{'User-Agent':'Mozilla/5.0'}); if(r.statusCode<200||r.statusCode>=400)throw Exception('HTTP ${r.statusCode}'); final h=r.body; String pick(String pattern){final m=RegExp(pattern,caseSensitive:false,dotAll:true).firstMatch(h);return m?.group(1)?.replaceAll(RegExp(r'<[^>]+>'),' ').replaceAll(RegExp(r'\s+'),' ').trim()??'';} final title=pick(r'<title[^>]*>(.*?)</title>'); final desc=pick(r'<meta[^>]+name=["\']description["\'][^>]+content=["\'](.*?)["\']'); return Property(code:'D-${DateTime.now().millisecondsSinceEpoch}',type:'آپارتمان',title:title.isEmpty?'فایل دیوار':title,address:'',owner:'',phone:'',price:'',area:'',rooms:'',year:'',link:url,desc:desc,agent:currentUser?.username??''); }}
